import json, collections, math
from cost_model import CostModel, align, HEADS, HIDDEN

cm=CostModel(64)
A=cm.c.Kd_attn; B=cm.c.Kd_mlp*HIDDEN
TdA=cm.c.Td_attn; TdB=cm.c.Td_mlp*HIDDEN

def dec_cost(S,G):
    return A*cm._sum_sq_arith(S,G)+B*(G*S+G*(G-1)/2)
def dec_lat(S,G):
    return TdA*cm._sum_sq_arith(S,G)+TdB*(G*S+G*(G-1)/2)
def batch_lat(S,G):
    return cm._prefill_lat(S)+dec_lat(S,G)+cm.c.Tbatch_overhead_ms

def load(f):
    return [json.loads(l) for l in open(f)]

def shape_compile_cost(S):
    return cm.c.Kshape_attn*S*S+cm.c.Kshape_mlp*S*HIDDEN

def best_shapes(smax_values,maxk=8):
    vals=sorted(set(smax_values))
    m=len(vals)
    INF=float('inf')
    # dp[j][i]
    dp=[[INF]*m for _ in range(maxk+1)]
    prev=[[-1]*m for _ in range(maxk+1)]
    for i in range(m):
        dp[1][i]=shape_compile_cost(vals[i])
    for j in range(2,maxk+1):
        best=INF; bi=-1
        for i in range(m):
            # min over p<i dp[j-1][p]
            if i>0 and dp[j-1][i-1]<best:
                best=dp[j-1][i-1]; bi=i-1
            if best<INF:
                dp[j][i]=best+shape_compile_cost(vals[i]); prev[j][i]=bi
    bestcost=INF; bestj=-1
    for j in range(1,maxk+1):
        if dp[j][m-1]<bestcost:
            bestcost=dp[j][m-1]; bestj=j
    # reconstruct reps
    reps=[]; j=bestj; i=m-1
    while j>=1:
        reps.append(vals[i])
        i=prev[j][i]; j-=1
    reps=sorted(reps)
    return bestcost,reps

def assign_shape(s,reps):
    for r in reps:
        if r>=s: return r
    return reps[-1]

def build_records(batches, reps):
    recs=[]
    for bi,b in enumerate(batches):
        bid=f'b-{bi:04d}'
        S=b['S']
        sr=assign_shape(S,reps)
        for r in b['members']:
            recs.append({'request_id':r['request_id'],'batch_id':bid,'shape':{'seq_align':sr,'heads_align':HEADS,'hidden_align':HIDDEN}})
    return recs

def evaluate(rs,batches,use_best_shapes=True):
    reqs={r['request_id']:r for r in rs}
    smax=[b['S'] for b in batches]
    if use_best_shapes:
        cc,reps=best_shapes(smax)
    else:
        reps=sorted(set(smax)); cc=sum(shape_compile_cost(s) for s in reps)
    recs=build_records(batches,reps)
    m=cm.plan_metrics(reqs,recs)
    return m,reps

def make_batches(rs,keyfn):
    groups=collections.defaultdict(list)
    for r in rs: groups[keyfn(r)].append(r)
    out=[]
    for k,mem in sorted(groups.items(), key=lambda kv:str(kv[0])):
        S=max(align(r['prompt_len'],64) for r in mem); G=max(r['gen_len'] for r in mem)
        out.append({'S':S,'G':G,'members':mem,'lat':batch_lat(S,G)})
    return out

def base_groups(rs):
    return make_batches(rs, lambda r:(align(r['prompt_len'],64),r['gen_len']))

if __name__=='__main__':
    for f,T in [('../task_file/input_data/requests_bucket_1.jsonl',2.1e6),('../task_file/input_data/requests_bucket_2.jsonl',2.1e5)]:
        rs=load(f)
        print('===',f)
        for name,key in [('G',lambda r:r['gen_len']),('S,G',lambda r:(align(r['prompt_len'],64),r['gen_len'])),
                         ('G,Scl128',lambda r:(r['gen_len'],(align(r['prompt_len'],64)+127)//128*128)),
                         ('G,Scl192',lambda r:(r['gen_len'],(align(r['prompt_len'],64)+191)//192*192)),
                         ('G,Scl256',lambda r:(r['gen_len'],(align(r['prompt_len'],64)+255)//256*256))]:
            b=make_batches(rs,key)
            m,reps=evaluate(rs,b)
            print(name,'n',len(b),{k:round(m[k],4) for k in ['cost','pad_ratio','p95_latency_ms','sequential_timecost']},'reps',reps)
